public class EditDistance {
    // 方法一：标准二维 DP
    public int minDistance(String w1, String w2) {
        int m = w1.length(), n = w2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) dp[i][0] = i;     // word1[0..i) → 空串：删除 i 次
        for (int j = 0; j <= n; j++) dp[0][j] = j;     // 空串 → word2[0..j)：插入 j 次
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (w1.charAt(i - 1) == w2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];        // 末字符相同，零代价继承
                } else {
                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],   // 替换
                              Math.min(dp[i - 1][j],            // 删除
                                       dp[i][j - 1]));          // 插入
                }
            }
        }
        return dp[m][n];
    }

    // 方法二：滚动数组 O(min(m,n)) 空间
    public int minDistanceOptimized(String w1, String w2) {
        // 保证 w1 较长，用 w2 长度做一维数组
        if (w1.length() < w2.length()) { String t = w1; w1 = w2; w2 = t; }
        int m = w1.length(), n = w2.length();
        int[] dp = new int[n + 1];
        for (int j = 0; j <= n; j++) dp[j] = j;         // 初始化第一行：空串 → word2[0..j)
        for (int i = 1; i <= m; i++) {
            int prevDiag = dp[0];                        // dp[i-1][j-1] 的旧值
            dp[0] = i;                                   // 更新左边界：word1[0..i) → 空串
            for (int j = 1; j <= n; j++) {
                int temp = dp[j];                        // 暂存 dp[i-1][j]，下轮作为 prevDiag
                if (w1.charAt(i - 1) == w2.charAt(j - 1)) {
                    dp[j] = prevDiag;                    // 相等：继承左上
                } else {
                    dp[j] = 1 + Math.min(prevDiag,       // 替换 (旧左上)
                              Math.min(dp[j],             // 删除 (旧上方，即 temp)
                                       dp[j - 1]));      // 插入 (当前行左侧)
                }
                prevDiag = temp;                         // 更新左上角
            }
        }
        return dp[n];
    }
}
